python.code:
def factorial(n):
    if n <= 1:
        return 1
    return n * factorial(n - 1)

java.code:
static long factorial(long n) {
    if (n <= 1) return 1;
    return n * factorial(n - 1);
}

javascript.code:
function factorial(n) {
  if (n <= 1) return 1;
  return n * factorial(n - 1);
}

